export const MCP_TEMPLATE_FILES: Record<string, string> = {
  ".gitignore": "/node_modules\n",
  "README.md": "# Studio starter (MCP server)\n\nA minimal Model Context Protocol server deployed as a Tencent EdgeOne Pages Function — a single HTTP\nendpoint (`functions/mcp-server/index.ts`) implementing the MCP JSON-RPC methods (`initialize`,\n`tools/list`, `tools/call`) a business assistant needs to discover and call this server's tools. No\nbuild step: EdgeOne runs the TypeScript directly as an edge function.\n\nReplace the example `get_hello_message` tool with one that does something real for the business —\nadd more the same way (push a new entry onto `TOOLS`).\n\nThis starter's architecture (an edge function exposing MCP over HTTP, no server process to run)\nfollows the same pattern as [TencentEdgeOne/self-hosted-pages-mcp](https://github.com/TencentEdgeOne/self-hosted-pages-mcp);\nthe code here is an original implementation against the published MCP spec, not copied from that\nrepo (which carries no license).\n",
  "functions/mcp-server/index.ts": "// Minimal MCP (Model Context Protocol) server exposed as a Tencent EdgeOne Pages Function — a single\n// HTTP endpoint implementing the MCP JSON-RPC methods a business assistant needs to discover and call\n// this server's tools. No server process, no build step: EdgeOne runs this file directly as an edge\n// function. Replace EXAMPLE_TOOL with a real one; add more the same way.\n\ninterface JsonRpcRequest {\n  jsonrpc: '2.0';\n  id?: string | number | null;\n  method: string;\n  params?: Record<string, unknown>;\n}\n\ninterface ToolDefinition {\n  name: string;\n  description: string;\n  inputSchema: Record<string, unknown>;\n  handler: (args: Record<string, unknown>) => Promise<string> | string;\n}\n\nconst TOOLS: ToolDefinition[] = [\n  {\n    name: 'get_hello_message',\n    description:\n      'Returns a friendly greeting. Replace this with a tool that does something real for your business.',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        name: { type: 'string', description: 'Who to greet.' },\n      },\n    },\n    handler: (args) => {\n      const name = typeof args.name === 'string' && args.name.trim() ? args.name.trim() : 'there';\n      return `Hello, ${name}! This MCP server is up and running.`;\n    },\n  },\n];\n\nconst PROTOCOL_VERSION = '2024-11-05';\n\nfunction jsonRpcResult(id: JsonRpcRequest['id'], result: unknown): Response {\n  return new Response(JSON.stringify({ jsonrpc: '2.0', id: id ?? null, result }), {\n    headers: { 'content-type': 'application/json' },\n  });\n}\n\nfunction jsonRpcError(id: JsonRpcRequest['id'], code: number, message: string): Response {\n  // JSON-RPC errors still reply with HTTP 200 — the error lives in the body, per the spec.\n  return new Response(JSON.stringify({ jsonrpc: '2.0', id: id ?? null, error: { code, message } }), {\n    status: 200,\n    headers: { 'content-type': 'application/json' },\n  });\n}\n\nexport async function onRequest({ request }: { request: Request }): Promise<Response> {\n  if (request.method !== 'POST') {\n    return new Response('Method not allowed — POST JSON-RPC requests only.', { status: 405 });\n  }\n\n  let body: JsonRpcRequest;\n  try {\n    body = await request.json();\n  } catch {\n    return jsonRpcError(null, -32700, 'Parse error: invalid JSON.');\n  }\n  if (body.jsonrpc !== '2.0' || typeof body.method !== 'string') {\n    return jsonRpcError(body.id ?? null, -32600, 'Invalid Request: expected a JSON-RPC 2.0 request.');\n  }\n\n  switch (body.method) {\n    case 'initialize':\n      return jsonRpcResult(body.id, {\n        protocolVersion: PROTOCOL_VERSION,\n        capabilities: { tools: {} },\n        serverInfo: { name: 'my-mcp-server', version: '0.1.0' },\n      });\n\n    // A notification (no reply expected per the spec) — 204 with no body is the correct response.\n    case 'notifications/initialized':\n      return new Response(null, { status: 204 });\n\n    case 'tools/list':\n      return jsonRpcResult(body.id, {\n        tools: TOOLS.map(({ name, description, inputSchema }) => ({ name, description, inputSchema })),\n      });\n\n    case 'tools/call': {\n      const toolName = body.params?.name;\n      const toolArgs = (body.params?.arguments as Record<string, unknown> | undefined) ?? {};\n      const tool = TOOLS.find((t) => t.name === toolName);\n      if (!tool) return jsonRpcError(body.id, -32602, `Unknown tool: ${String(toolName)}`);\n      try {\n        const text = await tool.handler(toolArgs);\n        return jsonRpcResult(body.id, { content: [{ type: 'text', text }] });\n      } catch (err) {\n        return jsonRpcResult(body.id, {\n          content: [{ type: 'text', text: err instanceof Error ? err.message : String(err) }],\n          isError: true,\n        });\n      }\n    }\n\n    default:\n      return jsonRpcError(body.id, -32601, `Method not found: ${body.method}`);\n  }\n}\n",
  "package.json": "{\n  \"name\": \"my-mcp-server\",\n  \"version\": \"0.1.0\",\n  \"scripts\": {},\n  \"devDependencies\": {\n    \"@types/node\": \"^20\",\n    \"typescript\": \"^5\"\n  }\n}\n",
  "tsconfig.json": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2020\",\n    \"lib\": [\"ES2020\"],\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"bundler\",\n    \"strict\": true,\n    \"noEmit\": true,\n    \"skipLibCheck\": true,\n    \"esModuleInterop\": true,\n    \"resolveJsonModule\": true,\n    \"isolatedModules\": true\n  },\n  \"include\": [\"functions/**/*.ts\"]\n}\n",
};
